<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])){header('Location: login.php');exit;} $id=(int)($_GET['id']??0);$config=require __DIR__.'/config.php';try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$s=$pdo->query("SELECT id,nombre FROM tiendas WHERE estado='activa' ORDER BY nombre")->fetchAll();$q=$pdo->prepare('SELECT * FROM productos WHERE id=?');$q->execute([$id]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Producto no encontrado.');}}catch(Throwable $e){http_response_code(500);exit('No se pudo cargar el producto.');}function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar producto</title><style>body{font-family:system-ui;background:#f6f3ee}main{max-width:650px;margin:30px auto}.card{background:#fff;padding:25px;border-radius:16px}label{display:block;margin:10px 0 4px}input,select,textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #ccc;border-radius:7px}button{margin-top:16px;padding:11px 18px;background:#886c42;color:#fff;border:0;border-radius:7px}a{color:#886c42}</style></head><body><main><p><a href="panel.php">← Panel</a></p><section class="card"><h1>Editar producto</h1><form method="post" action="producto-actualizar.php"><input type="hidden" name="id" value="<?=$p['id']?>"><label>Tienda</label><select name="tienda_id" required><?php foreach($s as $x):?><option value="<?=$x['id']?>" <?=$x['id']==$p['tienda_id']?'selected':''?>><?=h($x['nombre'])?></option><?php endforeach;?></select><label>Nombre</label><input name="nombre" required value="<?=h($p['nombre'])?>"><label>Descripción</label><textarea name="descripcion"><?=h((string)$p['descripcion'])?></textarea><label>Precio</label><input type="number" name="precio" min="0" step="0.01" required value="<?=h((string)$p['precio'])?>"><label>Precio de oferta</label><input type="number" name="precio_oferta" min="0" step="0.01" value="<?=h((string)($p['precio_oferta']??''))?>"><label>Estado</label><select name="estado"><option value="activo">Activo</option><option value="inactivo">Inactivo</option><option value="agotado">Agotado</option></select><button>Guardar cambios</button></form></section></main></body></html>
